			]
		}, { // 14 在庭院打开菜单
			desc: '页面是否为庭院_菜单未展开_只支持默认庭院皮肤与默认装饰',
			oper: [
				[right, 1280, 720, 1168, 592, 1230, 690, 1200]	// 在首页打开菜单
			]
		}, { // 15 点击阴阳寮
			desc: '页面是否为庭院_菜单已展开_只支持默认庭院皮肤与默认装饰',
			oper: [
				[center, 1280, 720, 544, 612, 594, 661, 1200]	// 点击阴阳寮
			]
		}, { // 16 判断是否为寮首页
			desc: [
				1280, 720,
				[
					[right, 1096, 630, 0xb1251f],
					[right, 1105, 662, 0xdbe3f1],
					[left, 45, 39, 0xf4e4a3],
					[center, 886, 644, 0xe0cbaa],
				]
			],
			oper: [
				[center, 1280, 720, 868, 627, 927, 684, 1200]	// 点击下方神社
			],
			retest: 1000
		}];
	operatorFunc(thisScript: Script, thisOperator: IFuncOperator[]): boolean {
		const thisconf = thisScript.scheme.config['600'];
		const nowHour = new Date().getHours();
		const nowDay = new Date().getDay();
		// 设置全局方案起始点
		thisScript.superGlobal.next_scheme_name = thisScript.scheme.schemeName;
		if (!thisScript.superGlobal.liao_activity_Switch) {// 首次执行,读取按钮状况
			thisScript.superGlobal.liao_activity_Switch = {
				'a_ctivity_gateOfHades': thisconf.a_ctivity_gateOfHades as boolean,
				'a_ctivity_dojo': thisconf.a_ctivity_dojo as boolean,
				'a_ctivity_dojo_again': false,
				'a_ctivity_hunt': thisconf.a_ctivity_hunt as boolean,
				'a_ctivity_narrow': thisconf.a_ctivity_narrow as boolean,
				'a_ctivity_banquet': thisconf.a_ctivity_banquet as boolean,
				'a_ctivity_huntBoss': thisconf.a_ctivity_huntBoss as boolean,
			};
		}
		// 判断用户是否有选择选项,全部选项为假则退出任务
		const allFalse = Object.values(thisScript.superGlobal.liao_activity_Switch).every(value => value === false);
		if (allFalse) {
			thisScript.myToast('任务执行完毕!');
			thisScript.superGlobal.next_scheme_name = null;
			thisScript.doPush(thisScript, { text: '已结束，请查看。', before() { thisScript.myToast('脚本即将停止，正在上传数据'); } });
			thisScript.rerun(thisconf.next_scheme);
			sleep(1000);
			return true;
		}
		if (thisScript.oper({
			id: 600,
			name: '进入寮神社界面',
			operator: [thisOperator[14], thisOperator[15], thisOperator[16]]
		})) {
			return true;
		}
		// 首次进入寮神社界面返回一次重新进，防止还有原来的缓存在里面
		if (thisScript.global.liao_cheak == -1 && thisScript.oper({
			id: 600,
			name: '寮神社界面',
			operator: [thisOperator[11]]
		})) {
			thisScript.global.liao_cheak++;
			thisScript.myToast('首次进入寮神社界面，退出重进');
			return true;
		}
		// 道馆活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo'] || thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo_again']) {
			if ((nowDay >= 1 && nowDay <= 4) ||
				((nowDay === 5 || nowDay === 6 || nowDay === 0) && !thisconf.a_ctivity_narrow)
			) {
				if (thisconf.admin && thisScript.oper({
					id: 600,
					name: '寮神社界面',
					operator: [{ desc: thisOperator[11].desc }]
				})) {
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo'] = false;
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo_again'] = false;
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_narrow'] = false;
					const next_scheme = thisconf.a_ctivity_dojo_select;
					thisScript.rerun(next_scheme);
					return true;
				}
				if (thisScript.oper({
					name: '检测_寮界面道馆是否已开启',
					operator: [thisOperator[12]]
				})) {
					return true;
				}
				if (thisScript.oper({
					name: '检测_道馆内',
					operator: [{
						desc: thisOperator[6].desc
					}]
				})) {
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo'] = false;
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo_again'] = false;
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_narrow'] = false;
					const next_scheme = thisconf.a_ctivity_dojo_select;
					thisScript.rerun(next_scheme);
					return true;
				}
				if (thisScript.oper({
					id: 600,
					name: '检测_道馆', // 道馆地图界面,集结中
					operator: [thisOperator[2]]
				})) {
					const point = thisScript.findMultiColor('道馆集结')
					if (point) {
						const oper = [
							point.x + 70,
							point.y - 110,
							point.x + 120,
							point.y - 80,
							1000
						];
						thisScript.regionClick([oper]);
					}
					return true;
				}
			} else {
				console.log('星期五六日执行狭间');
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo'] = false;
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo_again'] = false;
			}
		}
		// 周六首领退治活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_huntBoss']) {
			if (nowHour >= 10 && nowHour < 23 && nowDay === 6) {// 判断是否在周六10-23点
				if (thisScript.oper({
					name: '检测_首领退治是否已开启',
					operator: [thisOperator[0],]
				})) {
					return true;
				}
				if (thisScript.oper({
					name: '检测_是否为首领退治页面',
					operator: [thisOperator[7]]
				})) {
					// 关闭开关 传参 切换到退治
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_huntBoss'] = false;
					const next_scheme = thisconf.a_ctivity_huntBoss_select;
					thisScript.rerun(next_scheme);
					return true;
				}
			} else {
				console.log('退治 不在时间段');
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_huntBoss'] = false;
			}
		}
		// 宴会活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_banquet']) {
			let a_ctivity_banquet_time_one;// 判断星期几
			let a_ctivity_banquet_time_two;// 判断星期几
			switch (thisconf.a_ctivity_banquet_time[0]) {
				case '星期一':
					a_ctivity_banquet_time_one = 1;
					break;
				case '星期二':
					a_ctivity_banquet_time_one = 2;
					break;
				case '星期三':
					a_ctivity_banquet_time_one = 3;
					break;
				case '星期四':
					a_ctivity_banquet_time_one = 4;
					break;
				case '星期五':
					a_ctivity_banquet_time_one = 5;
					break;
				case '星期六':
					a_ctivity_banquet_time_one = 6;
					break;
				case '星期日':
					a_ctivity_banquet_time_one = 0;
					break;
				default:
					console.log('宴会时间设置错误');
					break;
			}
			switch (thisconf.a_ctivity_banquet_time[1]) {
				case '星期一':
					a_ctivity_banquet_time_two = 1;
					break;
				case '星期二':
					a_ctivity_banquet_time_two = 2;
					break;
				case '星期三':
					a_ctivity_banquet_time_two = 3;
					break;
				case '星期四':
					a_ctivity_banquet_time_two = 4;
					break;
				case '星期五':
					a_ctivity_banquet_time_two = 5;
					break;
				case '星期六':
					a_ctivity_banquet_time_two = 6;
					break;
				case '星期日':
					a_ctivity_banquet_time_two = 0;
					break;
				default:
					console.log('宴会时间设置错误');
					break;
			}
			if (a_ctivity_banquet_time_one === nowDay || a_ctivity_banquet_time_two === nowDay) {// 判断是否符合
				if (thisconf.admin && Object.entries(thisScript.superGlobal.liao_activity_Switch).every(
					([key, value]) => ['a_ctivity_gateOfHades', 'a_ctivity_hunt', 'a_ctivity_banquet'].includes(key) || value === false
				)) { // 其他开关为关时
					if (thisconf.admin && thisScript.oper({
						id: 600,
						name: '寮神社界面',
						operator: [{ desc: thisOperator[11].desc }]
					})) {
						thisScript.superGlobal.liao_activity_Switch['a_ctivity_banquet'] = false;
						const next_scheme = thisconf.a_ctivity_banquet_select;
						thisScript.rerun(next_scheme);
						return true;
					}
				}
				if (thisScript.oper({
					name: '检查_宴会是否已开启',
					operator: [thisOperator[1]]
				})) {
					// 关闭开关 传参 切换到宴会
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_banquet'] = false;
					const next_scheme = thisconf.a_ctivity_banquet_select;
					thisScript.rerun(next_scheme);
					return true;
				}
			} else {
				console.log('宴会 不在时间段内');
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_banquet'] = false;
			}
		}
		// 狭间活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_narrow']) {
			if (nowDay === 0 || nowDay === 5 || nowDay === 6) {// 判断星期几
				if (thisScript.oper({
					name: '寮神社_下滑',
					operator: [{ desc: thisOperator[13].desc }]
				})) {
					thisScript.regionBezierSwipe(thisOperator[13].oper[1], thisOperator[13].oper[0], [1200, 1500], 1000);
					thisScript.keepScreen();
				}
				if (thisScript.oper({
					name: '检测_狭间暗域是否已开启',
					operator: [thisOperator[9]]
				})) {
					return true;
				}
				if (thisScript.oper({
					name: '检测_是否为狭间暗域选择页',
					operator: [thisOperator[10]]
				})) {
					// 关闭开关 传参 切换到狭间
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_narrow'] = false;
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_dojo'] = false;
					const next_scheme = thisconf.a_ctivity_narrow_select;
					thisScript.rerun(next_scheme);
					return true;
				}
			} else {
				console.log('狭间 不在时间段');
				// 关闭狭间开关
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_narrow'] = false;
			}
		}
		// 狩猎战活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_hunt']) {
			// 星期一二三四, 是否在6 - 23点
			if ([1, 2, 3, 4].includes(nowDay) && nowHour >= 6 && nowHour < 23) {
				if (Object.entries(thisScript.superGlobal.liao_activity_Switch).every(
					([key, value]) => ['a_ctivity_gateOfHades', 'a_ctivity_hunt'].includes(key) || value === false
				)) { // 其他开关为关时
					if (thisScript.oper({
						name: '检测_狩猎战',
						operator: [thisOperator[3]],
					})) {
						return true;
					}
					if (thisScript.oper({
						name: '检测_是否在狩猎战界面',
						operator: [thisOperator[4]],
					})) {
						const next_scheme = thisconf.a_ctivity_hunt_select;
						// 关闭开关 传参 切换到狩猎战
						thisScript.superGlobal.liao_activity_Switch['a_ctivity_hunt'] = false;
						thisScript.rerun(next_scheme);
						return true;
					}
				}
			} else {
				console.log('狩猎战 不在时间段内');
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_hunt'] = false;
			}
		}
		// 阴门活动
		if (thisScript.superGlobal.liao_activity_Switch['a_ctivity_gateOfHades']) {
			// 判断星期五六七是否在17-23点
			if ((nowDay === 0 || nowDay === 5 || nowDay === 6) && nowHour >= 17 && nowHour < 23) {
				if (Object.entries(thisScript.superGlobal.liao_activity_Switch).every(
					([key, value]) => key === 'a_ctivity_gateOfHades' || value === false
				) && thisScript.oper({
					id: 600,
					name: '寮神社界面',
					operator: [{ desc: thisOperator[11].desc }]
				})) {// 其他开关为关时
					// 关闭开关 切换到阴门
					thisScript.superGlobal.liao_activity_Switch['a_ctivity_gateOfHades'] = false;
					const next_scheme = thisconf.a_ctivity_gateOfHades_select;
					thisScript.rerun(next_scheme);
					return true;
				}
			} else {
				// 非阴门活动时间,关闭阴门开关
				console.log('阴门 不在时间段内');
				thisScript.superGlobal.liao_activity_Switch['a_ctivity_gateOfHades'] = false;
				return true;
			}
		}
		if (thisScript.oper({
			id: 600,
			name: '寮神社界面',
			operator: [{ desc: thisOperator[11].desc }]
		})) {
			thisScript.global.liao_cheak++;
			const r = random(28000, 32000);
			thisScript.oper({
				id: 600,
				name: '寮神社界面返回',
				operator: [{ oper: thisOperator[11].oper }]
			})
			if (thisScript.global.liao_cheak < (thisconf.count as number)) {
				thisScript.myToast(`未开启寮活动,等待${Math.round(r / 1000)}秒后再次检测,剩余${(thisconf.count as number) - thisScript.global.liao_cheak}次`);
				log(thisScript.superGlobal.liao_activity_Switch);
				sleep(r);
				return true;
			} else if (thisScript.global.liao_cheak < (thisconf.count as number) + 1) {
				thisScript.myToast('执行次数完毕,检查狩猎战或阴界之门或宴会')
				if (thisconf.admin) {
					thisScript.superGlobal.liao_activity_Switch = {
						...thisScript.superGlobal.liao_activity_Switch,
						'a_ctivity_dojo': false,
						'a_ctivity_dojo_again': false,
						'a_ctivity_narrow': false,
						'a_ctivity_huntBoss': false,
					};
					return true;
				} else {
					thisScript.superGlobal.liao_activity_Switch = {
						...thisScript.superGlobal.liao_activity_Switch,
						'a_ctivity_dojo': false,
						'a_ctivity_dojo_again': false,
						'a_ctivity_narrow': false,
						'a_ctivity_banquet': false,
						'a_ctivity_huntBoss': false,
					};
					return true;
				}
			} else if (thisScript.global.liao_cheak < (thisconf.count as number) + 3) {
				thisScript.oper({
					id: 600,
					name: '寮神社界面返回',
					operator: [{ oper: thisOperator[11].oper }]
				})
				thisScript.myToast('未找到狩猎战或阴界之门或宴会');
				thisScript.superGlobal.next_scheme_name = null;
				log('600_thisScript.superGlobal.next_scheme_name:' + thisScript.superGlobal.next_scheme_name);
				thisScript.rerun('返回庭院')
				sleep(3000);
				return true;
			}
		}
		return false;
	}
}
